{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.saadaa_inventory_planning as WITH daily_sku_sales AS ( SELECT CAST(order_date AS DATE) AS date_day, case when (marketplace in (\'AMAZON\',\'WEBSITE\',\'MYNTRA PPMP\',\'CRED-API\',\'B2B\') OR (UPPER(marketplace) = \'AMAZON_FBA\' and (upper(warehouse) = \'AMAZON_FBA_XIR6_AUTO\' or upper(warehouse) = \'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\'))) AND warehouse <> \'HOLISOL - BLR\' then \'Main Warehouse\' when (lower(marketplace) like \'%fba%\' and (upper(warehouse) <> \'AMAZON_FBA_XIR6_AUTO\' or upper(warehouse) <> \'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\')) then \'FBA Warehouse\' when lower(warehouse) like \'%holisol - blr%\' then \'Holisol - BLR\' end as Warehouse, replace(replace(commonsku,\'-\',\'_\'),\'_\',\'\') sku, SUM(quantity) AS daily_quantity FROM maplemonk.saadaa_sales_consolidated_intermediate WHERE (order_type IS NULL OR lower(order_type) NOT LIKE \'%stock transfer%\') and marketplace in (\'AMAZON\',\'WEBSITE\',\'MYNTRA PPMP\',\'AMAZON_FBA\',\'CRED-API\',\'B2B\') and replace(replace(sku,\'-\',\'_\'),\'_\',\'\') is not null and not(order_status = \'CANCELLED\' or oms_order_status = \'CANCELLED\') GROUP BY 1,2,3 ), all_sku_dates AS ( SELECT DISTINCT c.date_day, d.sku, d.warehouse, FROM daily_sku_sales AS d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(CURRENT_DATE(), YEAR), CURRENT_DATE())) AS date_day ) AS c ), daily_inventory_snapshot AS ( SELECT d.date_day, replace(replace(d.sku,\'-\',\'_\'),\'_\',\'\') sku, case when location like \'%FBA%\' then \'FBA Warehouse\' when location = \'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\' then \'Main Warehouse\' when location = \'Holisol - BLR\' then \'Holisol - BLR\' end as Warehouse, CASE WHEN sum(cast(Available_Quantity as INT64)) > 0 THEN 1 ELSE 0 END AS has_inventory FROM all_sku_dates d LEFT JOIN maplemonk.easyecom_saada_inventory_snapshot i on lower(replace(replace(replace(i.sku,\'-\',\'_\'),\'_\',\'\'),\'`\',\'\')) = lower(replace(replace(d.sku,\'-\',\'_\'),\'_\',\'\')) and cast(d.date_day as date) = cast(left(i.report_generated_date,10) as date) GROUP BY 1,2,3 ), sales_metrics AS ( SELECT a.date_day, a.sku, a.warehouse, COALESCE(s.daily_quantity, 0) AS daily_quantity, COALESCE(i.has_inventory, 0) AS has_inventory_today, CASE WHEN l.Launch_date >= A.date_day THEN 1 ELSE 0 END has_been_launched, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS L7_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS L30_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS L45_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 89 PRECEDING AND CURRENT ROW) AS L90_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 364 PRECEDING AND CURRENT ROW) AS L365_day_sales, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS inventory_days_7, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS inventory_days_30, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS inventory_days_45, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 89 PRECEDING AND CURRENT ROW) AS inventory_days_90, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 364 PRECEDING AND CURRENT ROW) AS inventory_days_365 FROM all_sku_dates AS a LEFT JOIN daily_sku_sales AS s ON a.date_day = s.date_day AND a.sku = s.sku and lower(a.warehouse) = lower(s.warehouse) LEFT JOIN daily_inventory_snapshot AS i ON a.date_day = i.date_day AND a.sku = i.sku and lower(a.warehouse) = lower(i.warehouse) LEFT JOIN (select * from (select replace(marketplace_sku,\' \',\'\') skucode, commonsku, Product_Variant, row_number() over (partition by replace(replace(replace(marketplace_sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\') order by 1) rw from saadaa-wh.maplemonk.saadaa_final_sku_master ) where rw = 1 ) p ON lower(replace(a.sku,\' \',\'\')) = lower(replace(replace(replace(p.skucode,\'-\',\'_\'),\'_\',\'\'),\' \',\'\')) LEFT JOIN (select Product_Variant, cast(parse_date(\'%m/%d/%Y\',Product_Launch_Date) as date) Launch_date from maplemonk.saadaa_variant_launch_date qualify row_number() over (partition by lower(replace(Product_Variant,\' \',\'\')) order by Product_Launch_Date asc)=1 ) l ON lower(replace(p.Product_Variant,\' \',\'\')) = lower(replace(l.Product_Variant,\' \',\'\')) Order by 1 desc ), T1 AS ( SELECT *, COUNTIF(has_inventory_today=1) OVER (PARTITION BY sku,warehouse ORDER BY date_day desc) AS has_inventory_row FROM sales_metrics ), weighted AS ( SELECT sku, warehouse, SUM(case when has_been_launched = 1 and has_inventory_today = 1 then daily_quantity end) AS total_sales_in_last_45_inventory_days_post_launch, SUM(case when has_inventory_today = 1 then daily_quantity end) AS total_sales_in_last_45_inventory_days, sum(case when has_been_launched = 1 and has_inventory_today = 1 then has_inventory_today else 0 end) last_inventory_days FROM T1 WHERE has_inventory_row <= 45 GROUP BY sku,warehouse ), doq as ( SELECT date_day, sku, warehouse, p.rm_fabric_sku as RM_code, p.Dyed_Fabric_SKU, p.product_name, p.product_variant as Product_Variant, p.Color_Family as Color, p.Size, p.Category, p.Sub_Category, p.Fabric_Consumption_Average, L7_day_sales t7_quantity, (L30_day_sales - L7_day_sales) t730_quantity, (L45_day_sales - L30_day_sales) t73015_quantity, L45_day_sales as t45_quantity, safe_divide(L7_day_sales,inventory_days_7) as doq_7, safe_divide((L30_day_sales - L7_day_sales),(inventory_days_30 - inventory_days_7)) as doq_7_30, safe_divide((L45_day_sales - L30_day_sales),(inventory_days_45 - inventory_days_30)) as doq_30_45, safe_divide(L90_day_sales,inventory_days_90) as doq_90, safe_divide(L30_day_sales,inventory_days_30) as doq_30, safe_divide(L45_day_sales,inventory_days_45) as doq_45, safe_divide(L365_day_sales,inventory_days_365) as doq_365, FROM sales_metrics s LEFT JOIN (select * from (select replace(marketplace_sku,\' \',\'\') skucode, commonsku, product_name, cast(category as string) category, cast(sub_category as string) as sub_category, Categorytype, Dyed_Fabric_SKU, RM_Fabric_SKU, case when Fabric_Consumption_Average <> \'#N/A\' then cast(Fabric_Consumption_Average as float64) else 0 end Fabric_Consumption_Average, Color_Family, Product_Type, Product_Variant, Size, row_number() over (partition by replace(replace(replace(marketplace_sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\') order by 1) rw from saadaa-wh.maplemonk.saadaa_final_sku_master ) where rw = 1 ) p ON lower(replace(s.sku,\' \',\'\')) = lower(replace(replace(replace(p.skucode,\'-\',\'_\'),\'_\',\'\'),\' \',\'\')) ), monthly_doq as ( SELECT date_day, sku, warehouse, doq_30 as monthly_doq from doq where date_day = last_day(date_day) ), yearly_avg_doq as ( SELECT sku, warehouse, avg(m.monthly_doq) as yearly_doq FROM monthly_doq m WHERE date_diff(last_day(current_date()),date_trunc(date_day, month),day) < 365 GROUP BY sku,warehouse ), final_doq as ( SELECT d.*, w.total_sales_in_last_45_inventory_days, safe_divide(w.total_sales_in_last_45_inventory_days,45) as weighted_doq_45, (coalesce(ifnull(doq_7,0),ifnull(doq_7_30,0),ifnull(doq_30_45,0))*0.55 + coalesce(ifnull(doq_7_30,0),ifnull(doq_7,0),ifnull(doq_30_45,0))*0.3 + coalesce(ifnull(doq_30_45,0),ifnull(doq_7,0),ifnull(doq_7_30,0))*0.15)/0.95 weightage_doq, md.monthly_doq, yad.yearly_doq, cast(lt.lead__time as int64) as Lead_Time, 0 as Buffer_Days, cast(si.available_quantity as int64) as current_stock, cast(pg.po_pending_quantity as int64) as total_inprogress FROM doq d LEFT JOIN monthly_doq md on md.date_day = last_day(d.date_day) and md.sku = d.sku and md.warehouse = d.warehouse LEFT JOIN yearly_avg_doq yad on yad.sku = d.sku and yad.warehouse = d.warehouse LEFT JOIN weighted w on w.sku = d.sku and w.warehouse = d.warehouse LEFT JOIN (select date, sku, Warehouse, sum(available_quantity) available_quantity from (select cast(left(report_generated_date,10) as date) date, replace(replace(replace(replace(sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\'),\'`\',\'\') sku, case when location like \'%FBA%\' then \'FBA Warehouse\' when location = \'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\' then \'Main Warehouse\' when location = \'Holisol - BLR\' then \'Holisol - BLR\' else \'N/A\' end as Warehouse, cast(available_quantity as int64) available_quantity from maplemonk.easyecom_saada_inventory_snapshot ) GROUP BY 1,2,3 qualify row_number() over (partition by sku,warehouse order by date desc) =1 ) si on lower(si.sku) = lower(d.sku) and lower(si.warehouse) = lower(d.warehouse) LEFT JOIN (select sku, case when po_created_warehouse = \'SAADAA SUSTAINABLE DESIGNS AND TECHNOLOGIES PRIVATE LIMITED\' then \'Main Warehouse\' end as po_created_warehouse, sum(po_pending_quantity) as po_pending_quantity from maplemonk.saadaa_po_grn_mapping where grn_created_date is null and not(po_status like any (\'Rejected\',\'Waiting for Approval\',\'cancelled\')) group by 1,2 ) pg on lower(replace(replace(replace(pg.sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\')) = lower(d.sku) and lower(d.warehouse) = lower(pg.po_created_warehouse) LEFT JOIN (select sku, lead__time from maplemonk.gs_saadaa_sku_inv_planning qualify row_number() over (partition by lower(replace(replace(replace(sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\')) order by 1)=1) lt on lower(replace(replace(replace(lt.sku,\'-\',\'_\'),\'_\',\'\'),\' \',\'\')) = lower(d.sku) order by d.date_Day desc ), variant_doq as ( select date_day, warehouse, Product_Variant, sum(greatest(doq_365,weighted_doq_45)) v_doq from final_doq group by 1,2,3 ) select d.*, v.v_doq from final_doq d left join variant_doq v on v.date_day = d.date_day and v.Product_Variant = d.Product_Variant and v.warehouse = d.warehouse ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            